const raw = $input.first().json;
let out = String(raw.mergedResponse || '');
if (!out) {
  out = (raw.content && raw.content.parts && raw.content.parts[0] && raw.content.parts[0].text)
    || (raw.candidates && raw.candidates[0] && raw.candidates[0].content && raw.candidates[0].content.parts && raw.candidates[0].content.parts[0] && raw.candidates[0].content.parts[0].text)
    || raw.text || '';
}
const lines = String(out).trim().split('\n').map(l => l.trim()).filter(Boolean);
const line1 = (lines[0] || '').toLowerCase();
const line2 = (lines[1] || '').toLowerCase();
const line3 = lines.slice(2).join(' ').trim();

const VALID = ['interested','question','resend_request','referred','maybe','not_interested','stop','wrong_person','out_of_office','automated','existing_conversation','uncertain'];
// Longest and most specific tokens first, so resend_request is not eaten by a looser match.
const ORDER = ['existing_conversation','not_interested','resend_request','out_of_office','wrong_person','referred','automated','uncertain','question','interested','maybe','stop'];
let intent = '';
for (const k of ORDER) {
  if (line1.indexOf(k) !== -1 || line1.indexOf(k.replace(/_/g, ' ')) !== -1) { intent = k; break; }
}
if (!VALID.includes(intent)) intent = 'uncertain';

const confident = /\bhigh\b/.test(line2);

const resolved = $('Resolve Prospect Match').first().json || {};
const method = resolved.match_method || 'none';

let suggested_action = line3;

// A hot lead costs the client a credit, so it needs BOTH a confident 'interested' AND a strong match.
// A domain-only match can be a different person or a different conversation entirely.
if (intent === 'interested' && !confident) intent = 'question';
if (intent === 'interested' && method !== 'thread' && method !== 'email') {
  intent = 'question';
  suggested_action = 'Matched by company domain only, not by our email thread or the exact address we wrote to. Check that this is really a reply to our outreach before treating it as a lead.' + (line3 ? ' ' + line3 : '');
}

const NO_ACTION = ['not_interested','stop','wrong_person','out_of_office','automated'];
if (NO_ACTION.includes(intent)) {
  suggested_action = 'No action needed.';
} else if (!suggested_action) {
  if (intent === 'resend_request') suggested_action = 'Send them the original email again.';
  else if (intent === 'referred') suggested_action = 'Note the new contact they gave and reach out there.';
  else if (intent === 'existing_conversation') suggested_action = 'This is a reply to correspondence outside our outreach. Handle it as normal correspondence.';
  else if (intent === 'interested') suggested_action = 'Reply today with times you could talk.';
  else suggested_action = 'Read the reply and decide whether to answer.';
}

const prospect = $('Lookup Prospect').first().json;
const sender = $('Extract Sender').first().json;
return [{ json: {
  prospect_id: prospect.id,
  client_id: prospect.client_id,
  business_name: prospect.business_name || '',
  message_id: resolved.message_id || null,
  reply_text: sender.reply_text,
  intent,
  intent_confidence: confident ? 0.95 : 0.6,
  suggested_action
} }];

let src = null;
let method = 'none';
try { const a = $('Find Original Message').first().json; if (a && a.id) { src = a; method = 'thread'; } } catch (e) {}
if (!src) {
  try {
    const b = $('Find Latest Message For Prospect').first().json;
    if (b && b.id) {
      src = b;
      let em = null;
      try { em = $('Normalize Email Match').first().json; } catch (e) {}
      method = (em && em.id) ? 'email' : 'domain';
    }
  } catch (e) {}
}
if (!src) src = {};
return [{ json: {
  prospect_id: src.prospect_id || '',
  message_id: src.id || null,
  gmail_thread_id: src.gmail_thread_id || '',
  match_method: method
} }];

const sender = $('Extract Sender').first().json;
const email = (sender.sender_email || '').toLowerCase();
const text = (sender.reply_text || '').toLowerCase();

// Bounces: mail delivery failures - a real deliverability problem worth tracking.
const bounceSenderPatterns = ['mailer-daemon', 'postmaster', 'mailer_daemon', 'bounce@'];
const bounceTextPatterns = [
  "wasn't delivered", "was not delivered", "delivery status notification", "undeliverable",
  "delivery has failed", "delivery failed", "returned mail", "failure notice", "message could not be delivered"
];

// Auto-replies: out-of-office / generic acks / no-reply inboxes - not a bounce, not a real reply either.
const autoReplySenderPatterns = ['no-reply', 'noreply', 'donotreply', 'do-not-reply'];
const autoReplyTextPatterns = [
  "out of office", "automatic reply", "auto-reply", "autoreply", "this is an automated",
  "away from my desk", "away from the office", "on vacation", "on leave",
  "we have received your", "your request has been forwarded", "thank you for contacting",
  "we will respond to your email", "this mailbox is not monitored", "do not reply to this email"
];

let category = null; // 'bounced' | 'auto_reply' | null
let reason = null;

for (const p of bounceSenderPatterns) { if (email.includes(p)) { category = 'bounced'; reason = 'sender pattern: ' + p; break; } }
if (!category) { for (const p of bounceTextPatterns) { if (text.includes(p)) { category = 'bounced'; reason = 'text pattern: "' + p + '"'; break; } } }
if (!category) { for (const p of autoReplySenderPatterns) { if (email.includes(p)) { category = 'auto_reply'; reason = 'sender pattern: ' + p; break; } } }
if (!category) { for (const p of autoReplyTextPatterns) { if (text.includes(p)) { category = 'auto_reply'; reason = 'text pattern: "' + p + '"'; break; } } }

return [{ json: { is_automated: !!category, automated_category: category || '', automated_reason: reason || '' } }];

const prospect = $('Lookup Prospect').first().json;
const sender = $('Extract Sender').first().json;
const resolved = $('Resolve Prospect Match').first().json || {};
const auto = $('Detect Automated Sender').first().json;
const intent = auto.automated_category === 'bounced' ? 'bounced' : 'auto_reply';
return [{ json: {
  prospect_id: prospect.id,
  client_id: prospect.client_id,
  business_name: prospect.business_name || '',
  message_id: resolved.message_id || null,
  reply_text: sender.reply_text,
  intent,
  intent_confidence: 1.0,
  suggested_action: 'No action needed. (' + (auto.automated_reason || 'automated message detected') + ')'
} }];

let found = {};
try {
  const f = $('Find Prospect By Sender Email').first().json;
  if (f && f.id) found = f;
} catch (e) {}
return [{ json: { id: found.id || '', client_id: found.client_id || '', business_name: found.business_name || '' } }];

let found = {};
try {
  const f = $('Find Prospect By Domain').first().json;
  if (f && f.id) found = f;
} catch (e) {}
return [{ json: { id: found.id || '', client_id: found.client_id || '', business_name: found.business_name || '' } }];

const msg = $json;
const clientId = $('Client Loop').item.json.client_id;
return {
  from: msg.from || '',
  text: msg.body || msg.snippet || '',
  snippet: msg.snippet || '',
  threadId: msg.threadId || msg.thread_id || '',
  gmail_message_id: msg.id || '',
  _client_id: clientId
};

const email = $json;
const fromRaw = email.from || email.From || '';
const match = fromRaw.match(/<(.+?)>/);
const sender_email = (match ? match[1] : fromRaw).toLowerCase().trim();

const rawText = email.text || email.snippet || '';
const reply_text = rawText
  .split(/On .+? wrote:/)[0]
  .split(/^>.*$/m)[0]
  .split(/-----Original Message-----/)[0]
  .replace(/&#39;/g, "'")
  .replace(/&quot;/g, '"')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&nbsp;/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// --- Bounce detection on the raw envelope, independent of prospect matching ---
const lowText = String(rawText).toLowerCase();
const envelope = (sender_email + ' ' + String(email.from || '')).toLowerCase();
const isBounceSender = /mailer-daemon|postmaster|mail delivery (subsystem|system)|maildeliverysystem|bounce@/.test(envelope);
const isBounceText = /wasn't delivered|was not delivered|delivery status notification|undeliverable|delivery has failed|delivery failed|returned mail|failure notice|message could not be delivered|address not found|recipient address rejected|no such user|user unknown|mailbox (unavailable|full)|does not exist|couldn't be found|could not be found/.test(lowText);
const is_bounce = isBounceSender || isBounceText;

// --- Extract the failed recipient address from the bounce body ---
let bounce_recipient = '';
if (is_bounce) {
  const dsn = rawText.match(/Final-Recipient:\s*rfc822;\s*<?([^\s\r\n<>]+@[^\s\r\n<>]+)>?/i)
           || rawText.match(/Original-Recipient:\s*rfc822;\s*<?([^\s\r\n<>]+@[^\s\r\n<>]+)>?/i);
  if (dsn) bounce_recipient = dsn[1].toLowerCase();
  if (!bounce_recipient) {
    const all = (rawText.match(/[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}/g) || []).map(e => e.toLowerCase());
    const bad = /mailer-daemon|postmaster|no-?reply|do-?not-?reply|googlemail|mail\.gmail\.com|daemon|\.google\.com$/;
    const candidates = all.filter(e => !bad.test(e) && e !== sender_email);
    if (candidates.length) bounce_recipient = candidates[0];
  }
}

const match_email = (is_bounce && bounce_recipient) ? bounce_recipient : sender_email;

return {
  sender_email,
  match_email,
  is_bounce,
  bounce_recipient,
  reply_text,
  thread_id: email.threadId || '',
  gmail_message_id: email.gmail_message_id || '',
  _client_id: email._client_id || '',
  from: email.from || ''
};
